fn pairAdd(a: vec2<f32>, b: vec2<f32>) -> vec2<f32> {
  let sum = fpAdd(a.x, b.x);
  let delta = fpSub(sum, a.x);
  let error = fpAdd(fpAdd(fpAdd(fpSub(a.x, fpSub(sum, delta)), fpSub(b.x, delta)), a.y), b.y);
  let hi = fpAdd(sum, error);
  return vec2<f32>(hi, fpSub(error, fpSub(hi, sum)));
}
fn add(a: vec4<f32>, b: vec4<f32>) -> vec4<f32> {
  return vec4<f32>(pairAdd(a.xy, b.xy), pairAdd(a.zw, b.zw));
